import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('happy path and out of stock', async () => {
  const h = await createHost();
  assert.deepEqual(await h.cart('a'), null);
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.deepEqual(await h.cart('a'), { status: 'open', items: 0 });
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  await h.open('b'); await h.add('b');
  assert.deepEqual(await h.checkout('a'), { ok: true });
  await h.checkout('b');
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  const ra = msgs.find((m) => m.from === 'a')!;
  assert.deepEqual({ to: ra.to, action: ra.action, data: ra.data }, { to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.cart('b'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.returnCart('b')).ok, false);
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.add('a')).ok, false);
  const msgs2 = (await h.inFlight()).map(({ from, to, action, data }) => ({ from, to, action, data }));
  assert.equal(msgs2.length, 2);
  assert.ok(msgs2.some((m) => m.to === 'payments' && m.action === 'Refund' && JSON.stringify(m.data) === '{"amount":2}'));
  assert.ok(msgs2.some((m) => m.to === 'inventory' && m.action === 'Release' && JSON.stringify(m.data) === '{"qty":2}'));
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('declined and cancelling', async () => {
  const h = await createHost();
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
