  await h.acceptCards(); await h.retry('r'); await h.deliverAll();
  assert.deepEqual(await h.cart('r'), { status: 'paid', items: 1 });
  assert.deepEqual(await h.payments(), { charged: 1, declining: false });
  await h.returnCart('r'); await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  await h.open('c'); await h.add('c'); await h.checkout('c');
  assert.deepEqual(await h.cancel('c'), { ok: true });
